-- 
-- @param easing 缓动函数或函数名
-- @returns 缓动函数
local function getEasingFunction(self, easingName)
    if easingName == nil then
        easingName = "linear"
    end
    if type(easingName) == "function" then
        return easingName
    end
    local func = EasingFunctions[easingName]
    if type(func) ~= "function" then
        error(("The easing function name '" .. easingName) .. "' is invalid")
    end
    return func
end
--- 对 subject 对象执行缓动操作
-- 
-- @param subject 源对象
-- @param target 目标对象
-- @param initial 初始对象
-- @param clock 当前时钟
-- @param duration 持续时间
-- @param easing 缓动函数
local function performEasingOnSubject(self, subject, target, initial, clock, duration, easing)
    local t
    local b
    local c
    local d
    for k in pairs(target) do
        local v = target[k]
        if type(v) == "table" then
            performEasingOnSubject(
                nil,
                subject[k],
                v,
                initial[k],
                clock,
                duration,
                easing
            )
        else
            t = clock
            b = initial[k]
            c = v - initial[k]
            d = duration
            subject[k] = easing(
                nil,
                t,
                b,
                c,
                d
            )
        end
    end
end
